window.TIMING = {"source":"estimate","duration":276,"scenes":[[0,32.73],[32.73,63.21],[63.21,95.29],[95.29,153.41],[153.41,187.89],[187.89,224.37],[224.37,244.85],[244.85,276]],"cues":[[1.2,8],[8.42,14.82],[15.24,21.64],[22.06,32.06],[33.28,38.88],[39.3,46.9],[47.32,53.32],[53.74,62.54],[63.76,67.76],[68.18,78.58],[79,86.2],[86.62,94.62],[95.84,101.44],[101.86,113.06],[113.48,123.88],[124.3,133.1],[133.52,146.32],[146.74,152.74],[153.96,161.16],[161.58,172.38],[172.8,180.4],[180.82,187.22],[188.44,197.64],[198.06,208.06],[208.48,216.48],[216.9,223.7],[224.92,227.32],[227.74,233.34],[233.76,238.96],[239.38,244.18],[245.4,256.2],[256.62,263.02],[263.44,264.24],[264.66,268.66],[269.08,271.48]],"subs":[[1.15,4.4,"Modern online gaming platforms depend on reliable software,",0],[4.4,8.34,"efficient infrastructure and well-designed systems for generating random outcomes.",0],[8.37,11.62,"As platforms grow, operators keep evaluating technologies that",1],[11.62,15.16,"strengthen their infrastructure and create room for differentiation.",1],[15.19,19.24,"Sonicium Entropy, a technology initiative from Sonicium Quantum Lab Limited,",2],[19.24,21.98,"offers API-based access to quantum-randomness data.",2],[22.01,24.06,"In the next few minutes,",3],[24.06,28.06,"we will show how a casino platform can evaluate it,",3],[28.06,32.41,"connect to it, test it and assess its business value.",3],[33.23,39.22,"Quantum measurement is a physical process that can serve as a source of randomness.",4],[39.25,42.9,"Sonicium Entropy measures superconducting quantum processors, health-tests the results,",5],[42.9,47.24,"and uses them to seed a standards-based random bit generator.",5],[47.27,50.52,"The output is delivered through one documented endpoint,",6],[50.52,53.66,"with source details included in every response.",6],[53.69,58.14,"For a casino platform, the real question is where this capability",7],[58.14,62.89,"fits in the existing architecture, and what measurable value it adds.",7],[63.71,68.1,"Integration starts with the specific component that needs random data.",8],[68.13,72.58,"Game engines, account systems, transactions and monitoring tools have different requirements,",9],[72.58,75.38,"so Sonicium Entropy should be evaluated at",9],[75.38,78.92,"one appropriate backend integration point, not connected everywhere.",9],[78.95,83,"A controlled test application sends authenticated requests and measures latency,",10],[83,86.54,"throughput, availability, error handling, format compatibility and cost.",10],[86.57,90.62,"For live wagering, any change must also respect the game's",11],[90.62,94.97,"approved outcome-generation design, the applicable regulations and independent testing requirements.",11],[95.79,101.78,"Connecting starts with API access: an account, a service tier and its usage limits.",12],[101.81,105.86,"The platform receives an API key, which is stored server-side,",13],[105.86,109.06,"in a secret manager or protected environment variable,",13],[109.06,113.4,"and never in a browser, mobile app or public repository.",13],[113.43,118.68,"The backend calls GET slash v1 slash random, sending the key as a",14],[118.68,124.22,"Bearer token in the Authorization header, with the length and format it needs.",14],[124.25,128.3,"The response returns the random data in hex or base64,",15],[128.3,133.44,"along with its length, format, register and the time it was served.",15],[133.47,136.72,"Errors are explicit: 401 for an invalid key,",16],[136.72,139.92,"429 with a Retry-After header for rate limits,",16],[139.92,142.72,"and 503 while the entropy pool refills,",16],[142.72,146.66,"so the client can back off and retry safely.",16],[146.69,148.74,"Usage is tracked per key,",17],[148.74,153.09,"and can be exported as a signed record for audit.",17],[153.91,157.56,"The commercial value depends on how the platform uses",18],[157.56,161.5,"the service and on the benefits it can measure.",18],[161.53,164.38,"The most useful evaluation compares the current",19],[164.38,167.58,"randomness setup with the proposed integration: engineering hours,",19],[167.58,172.72,"integration cost, cost per million requests, latency, error rates and operating cost.",19],[172.75,176.4,"To be clear, quantum randomness does not increase a",20],[176.4,180.74,"casino's revenue or change the mathematical edge of its games.",20],[180.77,184.02,"The business case rests on measurable infrastructure value,",21],[184.02,187.57,"suitable applications and a commercially viable service agreement.",21],[188.39,192.04,"Consider an illustrative example: ten million requests a month,",22],[192.04,197.98,"a hypothetical service fee of five hundred dollars, and two thousand dollars to integrate.",22],[198.01,201.66,"With one hundred dollars a month in operating costs,",23],[201.66,205.26,"the first-year total is nine thousand two hundred dollars,",23],[205.26,208.4,"or about seventy-seven dollars per million requests.",23],[208.43,213.28,"If the platform independently verifies one thousand dollars a month in benefits,",24],[213.28,216.82,"the illustrative first-year return is about thirty percent.",24],[216.85,220.1,"These figures show the method only. They are",25],[220.1,224.05,"not Sonicium Entropy prices, customer results or guaranteed returns.",25],[224.87,227.66,"Evaluation works best in three stages.",26],[227.69,233.68,"First, a technical proof of concept confirms connectivity, authentication, response formats and baseline performance.",27],[233.71,239.3,"Second, a controlled pilot measures real workload performance, reliability, operating cost and compatibility.",28],[239.33,244.53,"Third, a commercial evaluation agrees pricing, service limits, support and production requirements.",29],[245.35,250.6,"The next step is a focused technical discussion to define the use case,",30],[250.6,256.54,"review the documentation, agree on a test workload and set the metrics that matter.",30],[256.57,259.82,"We invite your technical and business teams to",31],[259.82,263.36,"explore the platform and plan an evaluation together.",31],[263.39,264.58,"Sonicium Entropy.",32],[264.61,269,"Quantum randomness. API-driven integration. A new opportunity for technology collaboration.",33],[269.03,271.83,"Visit soniciumentropy.com to begin the conversation.",34]]};
